// Regression test for production CSP directives generated by scripts/postbuild.mjs.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const work = mkdtempSync(join(tmpdir(), 'mixquilt-postbuild-'));

try {
  mkdirSync(join(work, 'dist'));
  writeFileSync(join(work, 'dist/index.html'), '<!doctype html><html><head></head><body></body></html>');
  writeFileSync(join(work, 'dist/manifest.webmanifest'), JSON.stringify({ start_url: '/Mixquilt/' }));

  const result = spawnSync(process.execPath, [join(root, 'scripts/postbuild.mjs')], {
    cwd: work,
    env: { ...process.env, BASE_PATH: '/Mixquilt/' },
    encoding: 'utf8',
  });
  assert.equal(result.status, 0, result.stderr || result.stdout);

  const html = readFileSync(join(work, 'dist/index.html'), 'utf8');
  const policy = html.match(/http-equiv="Content-Security-Policy" content="([^"]+)"/)?.[1];
  assert.ok(policy, 'postbuild should inject a Content-Security-Policy meta tag');

  const directives = Object.fromEntries(policy.split('; ').map((directive) => {
    const [name, ...sources] = directive.split(' ');
    return [name, sources];
  }));
  assert.deepEqual(directives['script-src'], ["'self'", "'wasm-unsafe-eval'", 'blob:']);
  assert.deepEqual(directives['connect-src'], ["'self'", 'blob:']);
  assert.deepEqual(directives['worker-src'], ["'self'", 'blob:']);
  console.log('PASS production CSP allows blob modules only in the required script, connection, and worker directives');
} finally {
  rmSync(work, { recursive: true, force: true });
}
